class.description:
Useful for tests. Time only moves when [method poll] or [method advance_time] is called.
[codeblock]
var session := LocalLoopbackSession.new()
var server := session.get_server_peer()
var client := session.create_client_peer()
session.poll()

session.set_link_conditions(server, LocalLinkConditions.wifi())
[/codeblock]
